--- Who sells this, cheapest first?
function V.sources_for(item_id)
    local raw = V.sold_by[item_id]
    if raw == nil then return {} end
    local out = {}
    for _, v in ipairs(raw) do
        out[#out + 1] = { npc = v[1], zone = v[2], price = v[3], x = v[4], z = v[5] }
    end
    return out
end

return V
